def maxAverageOfPath(matrix):
    # Initialize the maximum cost to a very small number
    max_cost = float('-inf')

    # Initialize the list to store the maximum cost for each cell
    dp = [[float('inf')] * len(matrix[0]) for _ in range(len(matrix))]

    # Iterate over each cell in the matrix
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            # Update the maximum cost for the current cell
            if matrix[i][j] > max_cost:
                max_cost = matrix[i][j]
                dp[i][j] = max_cost

    # Calculate the average cost for each cell
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            dp[i][j] = (matrix[i][j] + matrix[i][j]) / 2

    # Calculate the maximum cost for each cell
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            dp[i][j] = max_cost

    # Calculate the average cost for each cell
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            average_cost = matrix[i][j] / matrix[i][j]
            dp[i][j] = average_cost

    # Return the maximum cost found
    return max(dp)
