def find_first_occurrence(arr, target):
    # Initialize the left and right pointers
    left, right = 0, len(arr) - 1

    # Perform binary search
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    # Return the index of the first occurrence of the target
    return left
